// Built-in GDTF library (public/gdtf-library, generated by scripts/gdtf-library.ts).
// Loaded only when the user searches it; picking a fixture copies it (plus its small icon as a
// data URL) into custom fixtures, so patched lights keep working offline without the library.
import type { FixtureDef } from "./dmx";
import { addCustomFixture } from "./custom-fixtures";

export type LibraryDef = FixtureDef & { icon?: string };
let cache: Promise<LibraryDef[]> | null = null;

export function loadGdtfLibrary(): Promise<LibraryDef[]> {
  cache ??= fetch("/gdtf-library/library.json").then((r) => {
    if (!r.ok) throw new Error("Library unavailable");
    return r.json() as Promise<LibraryDef[]>;
  }).catch((e) => { cache = null; throw e; });
  return cache;
}

/** Every word must appear in brand + model; returns at most `limit` hits. */
export function searchGdtfLibrary(list: LibraryDef[], query: string, limit = 40): LibraryDef[] {
  const words = query.toLowerCase().split(/\s+/).filter(Boolean);
  if (!words.length) return [];
  const out: LibraryDef[] = [];
  for (const d of list) {
    const hay = `${d.brand} ${d.model}`.toLowerCase();
    if (words.every((w) => hay.includes(w))) { out.push(d); if (out.length >= limit) break; }
  }
  return out;
}

async function iconDataUrl(file: string): Promise<string | undefined> {
  try {
    const blob = await (await fetch(`/gdtf-library/icons/${file}`)).blob();
    return await new Promise((res) => { const fr = new FileReader(); fr.onload = () => res(String(fr.result)); fr.onerror = () => res(undefined); fr.readAsDataURL(blob); });
  } catch { return undefined; }
}

export async function installGdtfFixture(d: LibraryDef): Promise<FixtureDef> {
  const { icon, ...rest } = d;
  const url = icon ? await iconDataUrl(icon) : undefined;
  const def: FixtureDef = { ...rest, ...(url ? { icon: url } : {}) };
  addCustomFixture(def);
  return def;
}
